struct Ref:H8SEmulator{void history(int r,int w){lastread=r;lastwrite=w;}};
struct Event{uint64_t time;uint32_t addr;uint8_t value;bool write;};
static bool observed(uint32_t a){return a<0x80||a==0xffffc5||a==0xffffc7||(a>=0xffffd2&&a<=0xffffd3)||(a>=0xfffe88&&a<=0xfffe91)||(a>=0xa900&&a<0xba00)||(a>=0x18000&&a<0x1a000)||(a>=0xba00&&a<0xd400)||(a>=0xfffd20&&a<0xfffd42)||a==0xfffe30||(a>=0x600000&&a<0x600010)||a==0xffffb2;}
struct RBus:H8SDevice{unsigned group=0;Ref&c;std::array<Event,32>e{};unsigned n=0;explicit RBus(Ref&v):c(v){}uint8_t read(uint32_t a)override{uint8_t v=a==0xffffc7?uint8_t(0):a==0x600004?uint8_t(group==1?16:7):c.memory[a];e[n++]={c.cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{e[n++]={c.cycles,a,v,true};c.memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
struct NBus:kstation::ControllerResourceBus{unsigned group=0;bool enabled=false;std::array<Event,32>e{};unsigned n=0;bool mapped(uint32_t a)const override{return observed(a);}uint8_t read(uint32_t a)override{uint8_t v=a==0xffffc7?uint8_t(0):a==0x600004?uint8_t(group==1?16:7):state_->memory[a];if(enabled)e[n++]={state_->cycles,a,v,false};return v;}void write(uint32_t a,uint8_t v)override{if(enabled)e[n++]={state_->cycles,a,v,true};state_->memory[a]=v;if(a==0x600000&&v==8)group=1;if(a==0x60000e)group=2;}};
int main(int argc,char**argv){if(argc!=2)return 77;std::ifstream f(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(f),{}};if(rom.size()!=49728)return 1;auto c=std::make_unique<Ref>();auto d=std::make_unique<kstation::ControllerDeviceState>();c->loadmem(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0);d->loadMemory(rom.data(),rom.size(),0x400000);RBus x(*c);NBus y;c->memmap(&x,0,0x80);c->memmap(&x,0xa900,0x1100);c->memmap(&x,0xba00,0x1a00);c->memmap(&x,0xffffc5,1);c->memmap(&x,0xffffc7,1);c->memmap(&x,0xffffd2,2);c->memmap(&x,0xfffe88,10);c->memmap(&x,0x18000,0x2000);c->memmap(&x,0xfffd20,0x22);c->memmap(&x,0xfffe30,1);c->memmap(&x,0x600000,16);c->memmap(&x,0xffffb2,1);d->attachBus(&y);auto midi=std::make_unique<kstation::ControllerMidiServices>();auto voice=std::make_unique<kstation::ControllerVoiceServices>();kstation::ControllerInterruptRuntime irq;kstation::ControllerDspTransferRuntime dsp;kstation::ControllerPanelHardwareRuntime panel;kstation::ControllerLcdRuntime lcd;kstation::ControllerNumericDisplayRuntime numeric;if(!panel.bindBootResources(*d,rom.data(),rom.size())||!panel.bindMirroredFirmware(*d,rom.data(),rom.size())||!irq.bindVerifiedFirmware(*d,rom.data(),rom.size())||!dsp.bindVerifiedFirmware(*d,rom.data(),rom.size())||!voice->bindAll(*d,rom.data(),rom.size())||!lcd.bindBootResources(*d,rom.data(),rom.size())||!numeric.bindBootResources(*d,rom.data(),rom.size())||!midi->bindAll(*d,rom.data(),rom.size()))return 2;y.enabled=true;using H=kstation::ControllerForegroundRuntime::MidiHandler;if(midi->startHandler(H::Unknown,3,0xcad3)||midi->active())return 3;uint64_t phases=0,events=0,shorts=0,returned=0;for(unsigned scenario=0;scenario<5;++scenario)for(unsigned flags:{0u,0x80u}){if(!midi->reset())return 4;irq.reset();dsp.reset();irq.setMask(flags?kstation::ControllerInterruptRuntime::Mask::Disabled:kstation::ControllerInterruptRuntime::Mask::Enabled);auto put=[&](uint32_t a,uint8_t v){c->memory[a]=d->memory[a]=v;};put(0xcad3,scenario==0?7:scenario==1?100:scenario==4?2:0);put(0xcad4,127);put(0xcad5,3);put(0xbb16,3);put(0xcc01,16);put(0xcbff,0);put(0xd022,0);put(0xd028,0);put(0xcd7c,0);put(0xcd7f,0);put(0xbb0e,0);put(0xbb14,3);put(0xcd0e,0);put(0xc598,0xff);put(0xc599,0xff);constexpr uint32_t entries[]={0x2e34,0x33ca,0x2f68,0x2f6c,0x33ca};constexpr H handlers[]={H::ControlChange,H::ProgramChange,H::SysExStart,H::SysExEnd,H::ProgramChange};c->pc=c->makepc(entries[scenario]);c->setSP(0xffff10);for(unsigned i=0;i<4;++i)c->memory[0xffff10+i]=uint8_t(0x7000u>>(8*(3-i)));c->reg32(4)=0xcad3;c->reg32(1)=0xca03;c->ccr=uint8_t(flags);c->pending_irqs=d->pendingIrqs=0;c->pending_irqs_high=d->pendingIrqsHigh=0;c->interruptMode2=d->interruptMode2=false;c->cycles=d->cycles=100000;c->history(-1,-1);d->lastRead=d->lastWrite=-1;x.group=y.group=0;if(!midi->startHandler(handlers[scenario],3,0xcad3))return 5;for(unsigned k=0;midi->active();++k){if(k>10000)return 6;auto route=midi->routeDirect(*d,irq,dsp,*voice,lcd,numeric,panel);if(route!=kstation::ControllerMidiServices::Route::Ready){std::fprintf(stderr,"route scenario=%u pc=%x owner=%u\n",scenario,c->getPC(),unsigned(midi->externalRequest(*voice).owner));return 7;}auto at=uint32_t(c->getPC());x.n=y.n=0;auto cost=midi->nextClocks(*d,irq,dsp,*voice);if(!cost)return 8;for(unsigned b=0;b<cost;++b){auto before=d->cycles;auto r=midi->advanceDirect(*d,irq,dsp,*voice,b);if(r.clocks||d->cycles!=before||y.n)return 9;++shorts;}c->step();auto r=midi->advanceDirect(*d,irq,dsp,*voice,cost);if(!r.clocks)return 10;if(r.returned)++returned;if(c->cycles!=d->cycles||x.n!=y.n){std::fprintf(stderr,"phase %x scenario=%u clocks=%llu/%llu io=%u/%u\n",at,scenario,c->cycles,d->cycles,x.n,y.n);return 11;}for(unsigned i=0;i<x.n;++i)if(x.e[i].time!=y.e[i].time||x.e[i].addr!=y.e[i].addr||x.e[i].value!=y.e[i].value||x.e[i].write!=y.e[i].write)return 12;events+=x.n;++phases;}if(c->getPC()!=0x7000)return 13;}if(returned!=10)return 14;std::printf("{\"passed\":true,\"graphs\":10,\"phases\":%llu,\"events\":%llu,\"short_budgets\":%llu}\n",(unsigned long long)phases,(unsigned long long)events,(unsigned long long)shorts);}
